CREATE TABLE public.notification_preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles(id),new_auctions boolean NOT NULL DEFAULT false,categories uuid[] NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.notification_preferences TO authenticated; GRANT ALL ON public.notification_preferences TO service_role; ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY; CREATE POLICY preferences_own ON public.notification_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.push_devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),token text NOT NULL UNIQUE CHECK(length(token) BETWEEN 20 AND 4096),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_devices TO authenticated; GRANT ALL ON public.push_devices TO service_role; ALTER TABLE public.push_devices ENABLE ROW LEVEL SECURITY; CREATE POLICY devices_own ON public.push_devices FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.auction_push_events(auction_id uuid PRIMARY KEY REFERENCES public.auctions(id),created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.auction_push_events TO service_role; ALTER TABLE public.auction_push_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.push_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auction_id uuid NOT NULL REFERENCES public.auctions(id),user_id uuid NOT NULL REFERENCES public.profiles(id),device_id uuid NOT NULL REFERENCES public.push_devices(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','failed','skipped')),claimed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(auction_id,device_id)); GRANT ALL ON public.push_outbox TO service_role; ALTER TABLE public.push_outbox ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.new_auction_notifications() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE event_id uuid; pref_row record; category_label text; BEGIN IF NEW.status='active' AND OLD.status IN ('draft','scheduled') THEN INSERT INTO public.auction_push_events(auction_id) VALUES(NEW.id) ON CONFLICT DO NOTHING RETURNING auction_id INTO event_id; IF event_id IS NULL THEN RETURN NEW; END IF; SELECT name INTO category_label FROM public.categories WHERE id=NEW.category_id; FOR pref_row IN SELECT p.user_id FROM public.notification_preferences p WHERE p.new_auctions AND p.user_id<>NEW.seller_id AND (cardinality(p.categories)=0 OR NEW.category_id=ANY(p.categories)) LOOP PERFORM public.notify(pref_row.user_id,NEW.title,coalesce(category_label,'Subasta')||' · Nueva subasta en NEXO','/subastas/'||NEW.id); END LOOP; INSERT INTO public.push_outbox(auction_id,user_id,device_id) SELECT NEW.id,d.user_id,d.id FROM public.push_devices d JOIN public.notification_preferences p ON p.user_id=d.user_id WHERE p.new_auctions AND d.user_id<>NEW.seller_id AND (cardinality(p.categories)=0 OR NEW.category_id=ANY(p.categories)) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER new_auction_notifications AFTER UPDATE ON public.auctions FOR EACH ROW EXECUTE FUNCTION public.new_auction_notifications();
CREATE OR REPLACE FUNCTION public.claim_push_batch(_limit integer DEFAULT 20) RETURNS TABLE(queue_id uuid,device_id uuid,device_token text,auction_id uuid,title text,category_name text,image_path text) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ WITH candidates AS (SELECT q.id FROM public.push_outbox q WHERE q.status='pending' ORDER BY q.created_at LIMIT least(greatest(_limit,1),20) FOR UPDATE SKIP LOCKED), claimed AS (UPDATE public.push_outbox q SET status='sending',claimed_at=now() FROM candidates c WHERE q.id=c.id RETURNING q.*) SELECT c.id,d.id,d.token,a.id,a.title,coalesce(cat.name,'Subasta'),CASE WHEN a.auction_type='item' THEN a.images[1] ELSE NULL END FROM claimed c JOIN public.push_devices d ON d.id=c.device_id JOIN public.notification_preferences p ON p.user_id=c.user_id AND p.new_auctions JOIN public.auctions a ON a.id=c.auction_id AND a.status='active' LEFT JOIN public.categories cat ON cat.id=a.category_id WHERE cardinality(p.categories)=0 OR a.category_id=ANY(p.categories) $$;
REVOKE ALL ON FUNCTION public.claim_push_batch(integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_push_batch(integer) TO service_role;